Object.assign(SHEETS_DATA, EXTRA_SHEETS);
const SHEETS = {};
function getSheet(name) {
  let s = SHEETS[name];
  if (s) return s;
  const [w, h, pal, b64] = SHEETS_DATA[name];
  const bin = atob(b64);
  const d = new Uint32Array(w * h);
  for (let i = 0; i < d.length; i++) d[i] = pal[bin.charCodeAt(i)] >>> 0;
  return (SHEETS[name] = { w, h, d });
}

function samplePx(sheet, x, y) {
  const s = getSheet(sheet);
  const cx = Math.max(0, Math.min(s.w - 1, x | 0));
  const cy = Math.max(0, Math.min(s.h - 1, y | 0));
  return s.d[cy * s.w + cx];
}

function boxStd(sheet, u, v, w, h, d, f, x, y, mirror = false) {
  let tx, ty;
  if (f === 2) { tx = u + d + (mirror ? w - 1 - x : x); ty = v + y; }
  else if (f === 3) { tx = u + d + w + (mirror ? w - 1 - x : x); ty = v + (d - 1 - y); }
  else if (f === 4) { tx = u + d + (mirror ? w - 1 - x : x); ty = v + d + y; }
  else if (f === 5) { tx = u + 2 * d + w + (mirror ? w - 1 - x : x); ty = v + d + y; }
  else if (f === 1) { tx = mirror ? u + d + w + (d - 1 - x) : u + x; ty = v + d + y; }
  else { tx = mirror ? u + (d - 1 - x) : u + d + w + x; ty = v + d + y; }
  return samplePx(sheet, tx, ty);
}

function boxRotX90(sheet, u, v, w, h, d, f, x, y) {
  let tx, ty;
  if (f === 4) { tx = u + h + x; ty = v + (h - 1 - y); }
  else if (f === 5) { tx = u + h + w + (w - 1 - x); ty = v + y; }
  else if (f === 3) { tx = u + h + x; ty = v + h + (d - 1 - y); }
  else if (f === 2) { tx = u + 2 * h + w + x; ty = v + h + (d - 1 - y); }
  else if (f === 1) { tx = u + y; ty = v + h + (d - 1 - x); }
  else { tx = u + h + w + (h - 1 - y); ty = v + h + x; }
  return samplePx(sheet, tx, ty);
}

// sample a pixel through up to three layered sheets (overlay > mid > base)
function box3(a, b, c, u, v, w, h, d, f, x, y, mirror = false) {
  let tx, ty;
  if (f === 2) { tx = u + d + (mirror ? w - 1 - x : x); ty = v + y; }
  else if (f === 3) { tx = u + d + w + (mirror ? w - 1 - x : x); ty = v + (d - 1 - y); }
  else if (f === 4) { tx = u + d + (mirror ? w - 1 - x : x); ty = v + d + y; }
  else if (f === 5) { tx = u + 2 * d + w + (mirror ? w - 1 - x : x); ty = v + d + y; }
  else if (f === 1) { tx = mirror ? u + d + w + (d - 1 - x) : u + x; ty = v + d + y; }
  else { tx = mirror ? u + (d - 1 - x) : u + d + w + x; ty = v + d + y; }
  let col = 0;
  for (const s of [c, b, a]) {
    const p = samplePx(s, tx, ty);
    if (p & 0xff) { col = p; break; }
  }
  return col || 0xff808080;
}

// ---- skins (official Minecraft 26.3 entity textures) -----------------------------------
const SKINS = {
  player: ({ part, face, x, y, tag }) => {
    if (tag) {
      const [, mat, slot] = tag.split('_');
      const sh = `armor_${mat}_${slot === '2' ? 2 : 1}`;
      if (part === 'head') return boxStd(sh, 0, 0, 8, 8, 8, face, x, y);
      if (part === 'body') return boxStd(sh, 16, 16, 8, 12, 4, face, x, y);
      if (part === 'armR') return boxStd(sh, 40, 16, 4, 12, 4, face, x, y);
      if (part === 'armL') return boxStd(sh, 40, 16, 4, 12, 4, face, x, y, true);
      if (part === 'legR') return boxStd(sh, 0, 16, 4, 12, 4, face, x, y);
      return boxStd(sh, 0, 16, 4, 12, 4, face, x, y, true);
    }
    if (part === 'head') return boxStd('player', 0, 0, 8, 8, 8, face, x, y);
    if (part === 'body') return boxStd('player', 16, 16, 8, 12, 4, face, x, y);
    if (part === 'armR') return boxStd('player', 40, 16, 4, 12, 4, face, x, y);
    if (part === 'armL') return boxStd('player', 32, 48, 4, 12, 4, face, x, y);
    if (part === 'legR') return boxStd('player', 0, 16, 4, 12, 4, face, x, y);
    return boxStd('player', 16, 48, 4, 12, 4, face, x, y);
  },
  zombie: ({ part, face, x, y }) => {
    if (part === 'head') return boxStd('zombie', 0, 0, 8, 8, 8, face, x, y);
    if (part === 'body') return boxStd('zombie', 16, 16, 8, 12, 4, face, x, y);
    if (part === 'armR') return boxStd('zombie', 40, 16, 4, 12, 4, face, x, y);
    if (part === 'armL') return boxStd('zombie', 40, 16, 4, 12, 4, face, x, y, true);
    if (part === 'legR') return boxStd('zombie', 0, 16, 4, 12, 4, face, x, y);
    return boxStd('zombie', 0, 16, 4, 12, 4, face, x, y, true);
  },
  // 26.3 breeze: official 32x32 ghost skin — wide glowing head band (y0-7),
  // smooth body band (y8-15) with a golden wind-core line, one trailing arm
  // (0,16,4,12) and two tiny feet (y27-31). Each box face is stretched over
  // its source band (samplePx clamps to the sheet edge).
  breeze: (() => {
    const reg = { head: [8, 0, 16, 8], body: [0, 8, 16, 8], back: [16, 8, 16, 8], arm: [0, 16, 8, 12], foot0: [3, 27, 5, 5], foot1: [15, 27, 5, 5] };
    const pick = (part, face) => {
      if (part === 'head') return reg.head;
      if (part === 'body') return face === 5 ? reg.back : reg.body;
      if (part === 'armR') return reg.arm;
      if (part === 'foot0') return reg.foot0;
      return reg.foot1;
    };
    return ({ part, face, x, y, w, h }) => {
      const [sx, sy, sw, sh] = pick(part, face);
      const px = sx + Math.min(sw - 1, Math.floor((x / Math.max(1, w)) * sw));
      const py = sy + Math.min(sh - 1, Math.floor((y / Math.max(1, h)) * sh));
      return samplePx('breeze', px, py) || 0xff808080;
    };
  })(),
  skeleton: ({ part, face, x, y }) => {
    if (part === 'head') return boxStd('skeleton', 0, 0, 8, 8, 8, face, x, y);
    if (part === 'body') return boxStd('skeleton', 16, 16, 8, 12, 4, face, x, y);
    if (part === 'armR') return boxStd('skeleton', 40, 16, 2, 12, 2, face, x, y);
    if (part === 'armL') return boxStd('skeleton', 40, 16, 2, 12, 2, face, x, y, true);
    if (part === 'legR') return boxStd('skeleton', 0, 16, 2, 12, 2, face, x, y);
    return boxStd('skeleton', 0, 16, 2, 12, 2, face, x, y, true);
  },
  creeper: ({ part, face, x, y }) => {
    if (part === 'head') return boxStd('creeper', 0, 0, 8, 8, 8, face, x, y);
    if (part === 'body') return boxStd('creeper', 16, 16, 8, 12, 4, face, x, y);
    return boxStd('creeper', 0, 16, 4, 6, 4, face, x, y, part === 'leg1' || part === 'leg3');
  },
  spider: ({ part, face, x, y }) => {
    if (part === 'head') return boxStd('spider', 32, 4, 8, 8, 8, face, x, y);
    if (part === 'neck') return boxStd('spider', 0, 0, 6, 6, 6, face, x, y);
    if (part === 'body') return boxStd('spider', 0, 12, 10, 8, 12, face, x, y);
    return boxStd('spider', 18, 0, 16, 2, 2, face, x, y, part.startsWith('legL'));
  },
  pig: ({ part, box, face, x, y }) => {
    if (part === 'body') return boxRotX90('pig', 28, 8, 10, 8, 16, face, x, y);
    if (part === 'head') return box === 1 ? boxStd('pig', 16, 16, 4, 3, 1, face, x, y) : boxStd('pig', 0, 0, 8, 8, 8, face, x, y);
    return boxStd('pig', 0, 16, 4, 6, 4, face, x, y, part === 'leg1' || part === 'leg3');
  },
  cow: ({ part, box, face, x, y }) => {
    if (part === 'body') return boxRotX90('cow', 18, 4, 12, 10, 18, face, x, y);
    if (part === 'head') return box > 0 ? boxStd('cow', 22, 0, 1, 3, 1, face, x, y) : boxStd('cow', 0, 0, 8, 8, 6, face, x, y);
    return boxStd('cow', 0, 16, 4, 12, 4, face, x, y, part === 'leg1' || part === 'leg3');
  },
  sheep: ({ part, face, x, y, tag }) => {
    const sh = tag === 'wool' ? 'sheep_wool' : 'sheep';
    if (part === 'body') return boxRotX90(sh, 28, 8, 8, 6, 16, face, x, y);
    if (part === 'head') return boxStd(sh, 0, 0, 6, 6, tag === 'wool' ? 6 : 8, face, x, y);
    return boxStd(sh, 0, 16, 4, tag === 'wool' ? 6 : 12, 4, face, x, y, part === 'leg1' || part === 'leg3');
  },
  chicken: ({ part, box, face, x, y }) => {
    if (part === 'body') return boxRotX90('chicken', 0, 9, 6, 6, 8, face, x, y);
    if (part === 'head') {
      if (box === 1) return boxStd('chicken', 14, 0, 4, 2, 2, face, x, y);
      if (box === 2) return boxStd('chicken', 14, 4, 2, 2, 2, face, x, y);
      return boxStd('chicken', 0, 0, 4, 6, 3, face, x, y);
    }
    if (part.startsWith('wing')) return boxStd('chicken', 24, 13, 1, 4, 6, face, x, y, part === 'wingL');
    return samplePx('chicken', 30, box === 0 ? 3 + (y % 5) : 3);
  },
  arrow: ({ box, x, y }) => {
    if (box === 0) return samplePx('arrow', 3 + (x % 9), 2);
    if (box === 1) return samplePx('arrow', 1 + (x & 1), 2);
    return samplePx('arrow', 13, 1 + (y & 1));
  },
  // first-person arm: built upside down (hand at +y), so flip y and swap top/bottom faces
  arm1p: ({ face, x, y, h, tag }) => {
    const f = face === 2 ? 3 : face === 3 ? 2 : face;
    const ny = face === 2 || face === 3 ? y : h - 1 - y;
    if (tag) {
      const [, mat] = tag.split('_');
      return boxStd(`armor_${mat}_1`, 40, 16, 4, 12, 4, f, x, ny);
    }
    return boxStd('player', 40, 16, 4, 12, 4, f, x, ny);
  },
};

export function drawPlayerPreview(c, armorMats = null) {
  c.width = 16; c.height = 32;
  const g = c.getContext('2d');
  const img = g.createImageData(16, 32);
  const d = img.data;
  const blit = (sh, sx, sy, dx, dy, w, h, flipX = false) => {
    for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
      const ux = flipX ? w - 1 - x : x;
      const col = samplePx(sh, sx + ux, sy + y);
      const a = col & 255;
      if (a < 16) continue;
      const i = ((dy + y) * 16 + (dx + x)) * 4;
      d[i] = (col >>> 24) & 255;
      d[i + 1] = (col >>> 16) & 255;
      d[i + 2] = (col >>> 8) & 255;
      d[i + 3] = a;
    }
  };
  blit('player', 8, 8, 4, 0, 8, 8);
  blit('player', 40, 8, 4, 0, 8, 8);
  blit('player', 20, 20, 4, 8, 8, 12);
  blit('player', 20, 36, 4, 8, 8, 12);
  blit('player', 44, 20, 0, 8, 4, 12);
  blit('player', 36, 52, 12, 8, 4, 12);
  blit('player', 4, 20, 4, 20, 4, 12);
  blit('player', 20, 52, 8, 20, 4, 12);
  if (armorMats) {
    if (armorMats[2]) {
      const sh = `armor_${armorMats[2]}_2`;
      blit(sh, 20, 20, 4, 8, 8, 12);
      blit(sh, 4, 20, 4, 20, 4, 12);
      blit(sh, 4, 20, 8, 20, 4, 12, true);
    }
    if (armorMats[3]) {
      const sh = `armor_${armorMats[3]}_1`;
      blit(sh, 4, 20, 4, 20, 4, 12);
      blit(sh, 4, 20, 8, 20, 4, 12, true);
    }
    if (armorMats[1]) {
      const sh = `armor_${armorMats[1]}_1`;
      blit(sh, 20, 20, 4, 8, 8, 12);
      blit(sh, 44, 20, 0, 8, 4, 12);
      blit(sh, 44, 20, 12, 8, 4, 12, true);
    }
    if (armorMats[0]) {
      const sh = `armor_${armorMats[0]}_1`;
      blit(sh, 8, 8, 4, 0, 8, 8);
    }
  }
  g.putImageData(img, 0, 0);
}

// ---- geometry ---------------------------------------------------------------------------
const box = (from, size, o = {}) => ({ from, size, ...o });
const quadLeg = (name, x, z, h) => ({ name, pivot: [x, h, z], boxes: [box([-2, -h, -2], [4, h, 4])] });
const bipedParts = (limb) => [
  { name: 'head', pivot: [0, 24, 0], boxes: [box([-4, 0, -4], [8, 8, 8])] },
  { name: 'body', pivot: [0, 0, 0], boxes: [box([-4, 12, -2], [8, 12, 4])] },
  { name: 'armR', pivot: [-5, 22, 0], boxes: [limb === 4 ? box([-3, -10, -2], [4, 12, 4]) : box([-1, -10, -1], [2, 12, 2])] },
  { name: 'armL', pivot: [5, 22, 0], boxes: [limb === 4 ? box([-1, -10, -2], [4, 12, 4]) : box([-1, -10, -1], [2, 12, 2])] },
  { name: 'legR', pivot: [-2, 12, 0], boxes: [limb === 4 ? box([-2, -12, -2], [4, 12, 4]) : box([-1, -12, -1], [2, 12, 2])] },
  { name: 'legL', pivot: [2, 12, 0], boxes: [limb === 4 ? box([-2, -12, -2], [4, 12, 4]) : box([-1, -12, -1], [2, 12, 2])] },
];
const spiderLegs = [];
for (let i = 0; i < 4; i++) {
  const z = [-2, -1, 0, 1][i];
  spiderLegs.push({ name: 'legR' + i, pivot: [-4, 9, z], boxes: [box([-15, -1, -1], [16, 2, 2])] });
  spiderLegs.push({ name: 'legL' + i, pivot: [4, 9, z], boxes: [box([-1, -1, -1], [16, 2, 2])] });
}
// villager: base skin + biome robe (type) + profession symbol, layered like vanilla
const villagerSkin = (typeSheet, profSheet) => ({ part, face, x, y }) => {
  if (part === 'head') return box3('villager_base', typeSheet, profSheet, 32, 0, 8, 8, 8, face, x, y);
  if (part === 'body') return box3('villager_base', typeSheet, profSheet, 16, 16, 8, 12, 4, face, x, y);
  if (part === 'armR') return box3('villager_base', typeSheet, profSheet, 40, 16, 4, 12, 4, face, x, y);
  if (part === 'armL') return box3('villager_base', typeSheet, profSheet, 32, 48, 4, 12, 4, face, x, y, true);
  if (part === 'legR') return box3('villager_base', typeSheet, profSheet, 0, 16, 4, 12, 4, face, x, y);
  return box3('villager_base', typeSheet, profSheet, 16, 48, 4, 12, 4, face, x, y, true);
};
const VILLAGER_TYPES = ['plains', 'desert', 'savanna', 'snow', 'taiga'];
const VILLAGER_PROFS = ['nitwit', 'farmer', 'fisherman', 'shepherd', 'butcher', 'leatherworker', 'mason', 'toolsmith',
  'weaponsmith', 'librarian', 'cleric', 'cartographer', 'fletcher', 'armorer'];
for (const t of VILLAGER_TYPES) for (const p of VILLAGER_PROFS) SKINS['villager_' + t + '_' + p] = villagerSkin('villager_type_' + t, 'villager_prof_' + p);
SKINS.iron_golem = ({ part, face, x, y }) => {
  if (part === 'head') return boxStd('iron_golem', 32, 0, 8, 6, 8, face, x, y);
  if (part === 'body') return boxStd('iron_golem', 16, 16, 10, 8, 12, face, x, y);
  if (part === 'armR') return boxStd('iron_golem', 40, 16, 4, 16, 4, face, x, y);
  if (part === 'armL') return boxStd('iron_golem', 40, 16, 4, 16, 4, face, x, y, true);
  if (part === 'legR') return boxStd('iron_golem', 0, 16, 4, 8, 4, face, x, y);
  return boxStd('iron_golem', 0, 16, 4, 8, 4, face, x, y, true);
};
SKINS.cat = ({ part, box, face, x, y }) => {
  if (part === 'head') {
    if (box === 1) return boxStd('cat', 16, 0, 1, 2, 1, face, x, y);
    if (box === 2) return boxStd('cat', 16, 0, 1, 2, 1, face, x, y, true);
    return boxStd('cat', 0, 0, 6, 6, 4, face, x, y);
  }
  if (part === 'tail') return boxStd('cat', 18, 0, 2, 2, 2, face, x, y);
  if (part === 'body') return boxStd('cat', 0, 12, 10, 8, 12, face, x, y);
  return boxStd('cat', 18, 2, 2, 5, 2, face, x, y);
};

